 993	  \caption{First Mover Advantage: The proportion of resources (tiles covered or points-for-finishing) that the first mover, \textit{P-Red}, secures across \PPC and \PTC contracts. There is a strong first-mover advantage for all models across all board types in \PPC, while contracts are more even in \PTC contracts.}
 994	  \label{fig:fma}
 995	\end{figure*}
